const tabId = 1675924496;
const itemDetails = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll("a[href*='/itm/']"));
  const uniqueItems = new Map();

  for (const a of links) {
    // Find item id from URL
    const match = a.href.match(/\/itm\/(\d+)/);
    if (!match) continue;
    const itmId = match[1];
    if (itmId === "123456") continue; // placeholder

    // Find closest container
    let container = a.closest(".s-item") || a.closest("[data-viewport]") || a.closest("li");
    if (!container) continue;

    if (!uniqueItems.has(itmId)) {
      const text = container.innerText;
      uniqueItems.set(itmId, {
        id: itmId,
        href: a.href.split("?")[0],
        text: text
      });
    }
  }
  return Array.from(uniqueItems.values());
});

