const { text } = await read("tmp://ebay_parsed_listings.json");
const listings = JSON.parse(text);

const filtered = [];
for (const item of listings) {
  const t = item.title.toLowerCase();
  const raw = item.fullText.toLowerCase();

  // Must be 3060 Ti or 3060ti
  const is3060Ti = (t.includes("3060 ti") || t.includes("3060ti") || t.includes("3060-ti"));
  // Must not be parts only
  const isParts = t.includes("for parts") || raw.includes("for parts") || t.includes("faulty") || t.includes("spares");
  // Must not be box only
  const isBoxOnly = t.includes("box only") || t.includes("empty box");
  // Must not be non-Ti 3060 (unless title explicitly has Ti)
  const isNonTiOnly = t.includes("3060") && !is3060Ti;
  // Must not be a full PC build unless it's just the card
  const isWholePC = t.includes("gaming pc") || t.includes("gaming desktop") || t.includes("full setup");

  if (is3060Ti && !isParts && !isBoxOnly && !isNonTiOnly && !isWholePC) {
    filtered.push(item);
  }
}

console.log(`Filtered down to ${filtered.length} potential functional RTX 3060 Ti listings:`);
for (let i = 0; i < Math.min(filtered.length, 20); i++) {
  const f = filtered[i];
  console.log(`${i+1}. [${f.id}] ${f.title} | Price: ${f.price} | Shipping: ${f.shipping} | Seller: ${f.sellerInfo}`);
}

await write("tmp://ebay_candidate_listings.json", JSON.stringify(filtered, null, 2));

const { text } = await read("tmp://ebay_candidate_listings.json");
const candidates = JSON.parse(text);

console.log(`Total candidates: ${candidates.length}`);

// Let's filter out anything over £500 or obviously spammy generic descriptions
const validCandidates = [];
for (const c of candidates) {
  // parse price
  const numMatch = c.price.match(/£([\d,]+(\.\d+)?)/);
  const priceVal = numMatch ? parseFloat(numMatch[1].replace(/,/g, "")) : 0;
  if (priceVal > 500) continue;

  // check shipping
  let shipVal = 0;
  if (c.shipping.includes("Free")) {
    shipVal = 0;
  } else {
    const sMatch = c.shipping.match(/£([\d,]+(\.\d+)?)/);
    if (sMatch) shipVal = parseFloat(sMatch[1].replace(/,/g, ""));
  }

  // Filter out listings that are obviously Chinese dropshippers with generic titles like "Graphics Card 1665MHz Core Frequency..."
  if (c.title.includes("1665MHz") || c.title.includes("High Performance For PC Gaming")) {
    continue;
  }

  validCandidates.push({
    ...c,
    priceVal,
    shipVal,
    totalPrice: (priceVal + shipVal).toFixed(2)
  });
}

console.log(`Valid candidates under £500: ${validCandidates.length}`);
validCandidates.slice(0, 18).forEach((c, idx) => {
  console.log(`${idx + 1}. [${c.id}] ${c.title} | Price: £${c.priceVal} + £${c.shipVal} = £${c.totalPrice} | Seller: ${c.sellerInfo}`);
});

await write("tmp://ebay_15_candidates.json", JSON.stringify(validCandidates.slice(0, 16), null, 2));

const tabId = 1675924496;

// Function to scrape listing details from an eBay item page
async function scrapeEbayItem(url) {
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });

  const details = await browserjs(tabId, () => {
    const title = document.querySelector("h1.x-item-title__mainTitle, .x-item-title")?.innerText.trim() || document.title;
    const price = document.querySelector(".x-price-primary, .x-bin-price, [data-testid='x-price-primary']")?.innerText.trim() || "";
    const shipping = document.querySelector(".ux-labels-values--shipping, [data-testid='ux-labels-values--shipping']")?.innerText.trim() || "";
    const condition = document.querySelector(".x-item-condition-text, [data-testid='x-item-condition-text']")?.innerText.trim() || "";
    const conditionDesc = document.querySelector(".x-item-condition-dialog")?.innerText.trim() || "";
    const returns = document.querySelector(".ux-labels-values--returns, [data-testid='ux-labels-values--returns']")?.innerText.trim() || "";
    const seller = document.querySelector(".x-sellercard-atf__info__about-seller, [data-testid='x-sellercard-atf__info__about-seller']")?.innerText.trim() || "";

    // Description text (inside iframe or container)
    let desc = "";
    const descIframe = document.querySelector("#desc_ifr");
    if (descIframe && descIframe.contentDocument) {
      desc = descIframe.contentDocument.body.innerText.trim().slice(0, 500);
    } else {
      desc = document.querySelector(".d-item-description, #desc_div")?.innerText.trim().slice(0, 500) || "";
    }

    // Item specifics
    const specifics = {};
    document.querySelectorAll(".ux-layout-section-evo__item").forEach(item => {
      const label = item.querySelector(".ux-labels-values__labels")?.innerText.trim();
      const val = item.querySelector(".ux-labels-values__values")?.innerText.trim();
      if (label && val) specifics[label] = val;
    });

    // Photos count
    const photoCount = document.querySelectorAll(".ux-image-filmstrip-carousel-item, .filmstrip-thumbnail, [data-testid='ux-image-filmstrip-carousel-item']").length || document.querySelectorAll(".ux-image-carousel-item").length;

    // Auction vs Buy It Now
    const isAuction = !!document.querySelector(".x-bid-button, #bidBtn_btn, [data-testid='x-bid-action']");
    const bidCount = document.querySelector(".x-bid-count, [data-testid='x-bid-count']")?.innerText.trim() || "";

    return {
      title,
      price,
      shipping,
      condition,
      conditionDesc,
      returns,
      seller,
      desc,
      specifics,
      photoCount,
      isAuction,
      bidCount
    };
  });

  return details;
}

