const { text } = await read("tmp://ebay_parsed_listings.json");
const listings = JSON.parse(text);

const filtered = [];
for (const item of listings) {
  const t = item.title.toLowerCase();
  const raw = item.fullText.toLowerCase();

  // Must be 3060 Ti or 3060ti
  const is3060Ti = (t.includes("3060 ti") || t.includes("3060ti") || t.includes("3060-ti"));
  // Must not be parts only
  const isParts = t.includes("for parts") || raw.includes("for parts") || t.includes("faulty") || t.includes("spares");
  // Must not be box only
  const isBoxOnly = t.includes("box only") || t.includes("empty box");
  // Must not be non-Ti 3060 (unless title explicitly has Ti)
  const isNonTiOnly = t.includes("3060") && !is3060Ti;
  // Must not be a full PC build unless it's just the card
  const isWholePC = t.includes("gaming pc") || t.includes("gaming desktop") || t.includes("full setup");

  if (is3060Ti && !isParts && !isBoxOnly && !isNonTiOnly && !isWholePC) {
    filtered.push(item);
  }
}

console.log(`Filtered down to ${filtered.length} potential functional RTX 3060 Ti listings:`);
for (let i = 0; i < Math.min(filtered.length, 20); i++) {
  const f = filtered[i];
  console.log(`${i+1}. [${f.id}] ${f.title} | Price: ${f.price} | Shipping: ${f.shipping} | Seller: ${f.sellerInfo}`);
}

await write("tmp://ebay_candidate_listings.json", JSON.stringify(filtered, null, 2));

