const { text } = await read("tmp://ebay_candidate_listings.json");
const candidates = JSON.parse(text);

console.log(`Total candidates: ${candidates.length}`);

// Let's filter out anything over £500 or obviously spammy generic descriptions
const validCandidates = [];
for (const c of candidates) {
  // parse price
  const numMatch = c.price.match(/£([\d,]+(\.\d+)?)/);
  const priceVal = numMatch ? parseFloat(numMatch[1].replace(/,/g, "")) : 0;
  if (priceVal > 500) continue;

  // check shipping
  let shipVal = 0;
  if (c.shipping.includes("Free")) {
    shipVal = 0;
  } else {
    const sMatch = c.shipping.match(/£([\d,]+(\.\d+)?)/);
    if (sMatch) shipVal = parseFloat(sMatch[1].replace(/,/g, ""));
  }

  // Filter out listings that are obviously Chinese dropshippers with generic titles like "Graphics Card 1665MHz Core Frequency..."
  if (c.title.includes("1665MHz") || c.title.includes("High Performance For PC Gaming")) {
    continue;
  }

  validCandidates.push({
    ...c,
    priceVal,
    shipVal,
    totalPrice: (priceVal + shipVal).toFixed(2)
  });
}

console.log(`Valid candidates under £500: ${validCandidates.length}`);
validCandidates.slice(0, 18).forEach((c, idx) => {
  console.log(`${idx + 1}. [${c.id}] ${c.title} | Price: £${c.priceVal} + £${c.shipVal} = £${c.totalPrice} | Seller: ${c.sellerInfo}`);
});

await write("tmp://ebay_15_candidates.json", JSON.stringify(validCandidates.slice(0, 16), null, 2));

