const tabId = 1675924555;
const amazonItems = await browserjs(tabId, () => {
  // Click cookie accept if exists
  const cookieBtn = document.getElementById("sp-cc-accept");
  if (cookieBtn) cookieBtn.click();

  const results = [];
  const cards = document.querySelectorAll("[data-component-type='s-search-result']");
  for (const card of cards) {
    const titleEl = card.querySelector("h2 a span, h2 span");
    const priceWhole = card.querySelector(".a-price-whole");
    const priceFraction = card.querySelector(".a-price-fraction");
    const linkEl = card.querySelector("h2 a");
    const ratingEl = card.querySelector(".a-icon-alt");
    const reviewsEl = card.querySelector("[aria-label*='stars'] ~ span, a .a-size-base");
    const deliveryEl = card.querySelector(".a-row.a-size-base.a-color-secondary.s-align-children-center");

    const title = titleEl ? titleEl.innerText.trim() : "";
    let price = "";
    if (priceWhole) {
      price = `£${priceWhole.innerText.replace(/\n|,/g, "").trim()}.${priceFraction ? priceFraction.innerText.trim() : "00"}`;
    }
    const link = linkEl ? linkEl.href : "";
    const rating = ratingEl ? ratingEl.innerText.trim() : "";
    const reviews = reviewsEl ? reviewsEl.innerText.trim() : "";

    if (title && (title.toLowerCase().includes("3060 ti") || title.toLowerCase().includes("3060ti"))) {
      results.push({
        title,
        price,
        link,
        rating,
        reviews
      });
    }
  }
  return results;
});

console.log(`Found ${amazonItems.length} RTX 3060 Ti items on Amazon UK:`);
console.log(JSON.stringify(amazonItems.slice(0, 10), null, 2));
await write("tmp://amazon_results.json", JSON.stringify(amazonItems, null, 2));

